    } catch (error) {
        // Remove only our tool and request hooks. Keep the diagnostic button until unload.
        try { if (ownedTool && findTool() === ownedTool) context.unregisterFunctionTool(TOOL_NAME); } catch {}
        ownedTool = undefined;
        setState('setup', error instanceof Error ? error.message : '脚本启动失败。');
        const r = waveRecovery(state.reason);
        notify('error', `资料整理未启动。原因：${r.cause} 怎么办：${r.remedy} 具体提示：${state.reason}`);
        void ui.open();
        return { dispose:cleanup, getStatus:() => structuredClone(state), openStatus:ui.open };
    }
}

const WAVE_SHIELD_STATE = { refreshUi: null };
const WAVE_SHIELD_FETCHES = [];
function waveShieldHostWindow() {
    try { if (window.top && window.top !== window) return window.top; } catch {}
    try { if (window.parent && window.parent !== window) return window.parent; } catch {}
    return window;
}

function waveShieldIsGenerateUrl(url) {
    try {
        const base = waveShieldHostWindow().location;
        const target = new URL(url, base.href);
        return target.origin === base.origin && target.pathname === '/api/backends/chat-completions/generate';
    } catch { return false; }
}

function waveShieldInstallFetch() {
    for (const win of [waveShieldHostWindow(), window]) {
        try {
            if (!win || typeof win.fetch !== 'function' || win.fetch.__WAVE_SHIELD_HOOK__) continue;
            const original = win.fetch.bind(win);
            const wrapped = async function (input, init) {
                let route = '';
                let outPlan = null;
                try {
                    route = typeof input === 'string' ? input : (input && typeof input.url === 'string' ? input.url : '');
                    if (init && typeof init.body === 'string' && String(init.method ?? input?.method ?? 'GET').toUpperCase() === 'POST'
                        && waveShieldIsGenerateUrl(route) && waveTakeRegisteredRequest(init.body)) {
                        let body = null;
                        try { body = JSON.parse(init.body); } catch (e) { body = null; }
                        if (body && typeof body === 'object') {
                            outPlan = waveOutPrepare(body);
                            globalThis.reportScriptPhase?.('输出通道', outPlan?.mode ?? '跳过');
                            init = Object.assign({}, init, { body: JSON.stringify(body) });
                        }
                    }
                } catch (e) { WAVE_OUT_STATE.error = describeError(e); throw e; }
                const response = await original.call(this, input, init);

                if (outPlan) return await waveOutRewrite(response, outPlan);
                return response;
            };
            wrapped.__WAVE_SHIELD_HOOK__ = true;
            win.fetch = wrapped;
            WAVE_SHIELD_FETCHES.push({ win, original, wrapped });
            WAVE_SHIELD_STATE.fetchMode = true;
        } catch (e) {}
    }
}

function waveShieldRestoreFetch() {
    while (WAVE_SHIELD_FETCHES.length) {
        const record = WAVE_SHIELD_FETCHES.pop();
        try { if (record.win.fetch === record.wrapped) record.win.fetch = record.original; } catch {}
    }
}


/* ===================================================================
 * 输出通道（防截断）
 * 两种走法：
 *   原生 —— 请求里挂 actual_content 工具，正文写进工具参数，回包再还原（默认）
 *   文本 —— 渠道不支持原生工具时，让模型把正文写在两个标记之间，由本脚本
 *           自己扫出来还原，全程不依赖任何工具能力
 * 移植自「防截断（S喵 昆仑）」的输出防截断部分；不含全防截断与独立悬浮窗。
 * =================================================================== */

const WAVE_OUT_TOOL = 'actual_content';
const WAVE_OUT_STORAGE_KEY = 'wave-out-channel-v1';
const TOOL_DESCRIPTION = '浪潮，把这一轮的全部输出都写到这里';
const TOOL_PREFIX = 'emit_complete_response_';
const WAVE_OUT_OPEN = '<wave_delivery>';
const WAVE_OUT_CLOSE = '</wave_delivery>';
const WAVE_OUT_MODES = ['auto', 'native', 'text', 'off'];
const WAVE_OUT_STATE = {
    mode: 'auto', unescape: false, loaded: false, turns: 0, lastChars: 0,
    lastTime: '', lastMode: '', skip: '', error: '',
};

const Logger = { info() {}, warn() {}, error() {}, log() {} };
const AntiTruncationDebugger = {
    log() {}, recordChunk() {}, recordToolCall() {}, startTrace() {},
    recordStats(stats) { waveOutNote(stats, ''); },
};
const FloatingMonitor = {
    append() {}, set() {}, startSession() {}, finishSession() {}, setMode() {},
};

function describeError(error) {
    try { return String((error && (error.message || error)) || '未知错误'); } catch (e) { return '未知错误'; }
}

function waveOutReadConfig() {
    const saved = getVariables({type:'script'})[WAVE_OUT_STORAGE_KEY] || {};
    WAVE_OUT_STATE.mode = WAVE_OUT_MODES.includes(saved.mode) ? saved.mode : 'auto';
    WAVE_OUT_STATE.unescape = saved.unescape === true;
    return { mode: WAVE_OUT_STATE.mode, unescape: WAVE_OUT_STATE.unescape };
}

function waveOutSaveConfig(partial) {
    const next = { ...waveOutReadConfig(), ...partial };
    insertOrAssignVariables({ [WAVE_OUT_STORAGE_KEY]: next }, {type:'script'});
    return waveOutReadConfig();
}

function waveOutCycleMode() {
    const index = WAVE_OUT_MODES.indexOf(WAVE_OUT_STATE.mode);
    const next = WAVE_OUT_MODES[(index + 1) % WAVE_OUT_MODES.length];
    const result = waveOutSaveConfig({ mode: next });
    if (typeof WAVE_SHIELD_STATE.refreshUi === 'function') { try { WAVE_SHIELD_STATE.refreshUi(); } catch (e) {} }
    return result;
}

// Only undo one extra layer when explicitly enabled; keep unknown and trailing backslashes.
function waveOutDecodeText(text, enabled) {
    if (!enabled || typeof text !== 'string') return text;
    const escapes = { n: '\n', r: '\r', t: '\t', '"': '"', '\\': '\\' };
    return text.replace(/\\([nrt"\\])/g, (_, key) => escapes[key]);
}

function waveOutNote(stats, reason) {
    if (stats) {
        WAVE_OUT_STATE.turns += 1;
        WAVE_OUT_STATE.lastChars = Number(stats.emittedChars || stats.chars || 0) || 0;
        WAVE_OUT_STATE.lastTime = new Date().toLocaleTimeString('zh-CN', { hour12: false });
        WAVE_OUT_STATE.lastMode = stats.plainWon ? '正文（未走通道）' : (stats.textMode ? '文本标记' : '工具参数');
    }
    if (reason) WAVE_OUT_STATE.skip = String(reason).slice(0, 120);
    if (typeof WAVE_SHIELD_STATE.refreshUi === 'function') { try { WAVE_SHIELD_STATE.refreshUi(); } catch (e) {} }
}

﻿/* ---------------- 请求整形 ---------------- */
function waveOutSkipReason(body) {
    if (!body || typeof body !== 'object') return '请求体不是对象';
    if (!Array.isArray(body.messages) || !body.messages.length) return '没有对话消息';
    if (body.tool_choice === 'none') return '本轮禁用了工具调用';
    if (body.tool_choice === 'required') return '本轮强制了工具调用';
    if (body.tool_choice && typeof body.tool_choice === 'object') return '本轮固定了某个工具';
    if (body.json_schema) return '本轮指定了结构化输出';
    if (body.response_format && body.response_format.type && body.response_format.type !== 'text') return '本轮指定了结构化输出';
    if (body.enable_web_search || body.use_google_search || body.use_url_context) return '本轮开启了联网或搜索';
    const tools = Array.isArray(body.tools) ? body.tools : [];
    if (tools.some(t => t && t.function && t.function.name === WAVE_OUT_TOOL)) return '请求里已经有同名工具';
    for (const m of body.messages) {
        if (!m || typeof m !== 'object') return '消息格式未知';
        if (m.role === 'tool' || m.tool_call_id) return '历史里有工具结果';
        if (Array.isArray(m.tool_calls) && m.tool_calls.length) return '历史里有工具调用';
        if (m.function_call) return '历史里有工具调用';
    }
    return '';
}

function waveOutTextInstruction() {
    return '【本轮交付方式】把这一轮要交的全部内容（含所有约定标签）写进下面两个标记之间，'
        + '标记之外不要写任何正文、说明或第二份稿子。换行写真实的换行。\n'
        + WAVE_OUT_OPEN + '\n（这里放完整正文）\n' + WAVE_OUT_CLOSE;
}

function waveOutPrepare(body) {
    const prefs = getContext().getGenerationScriptVariables()[WAVE_OUT_STORAGE_KEY] || {};
    const mode = WAVE_OUT_MODES.includes(prefs.mode) ? prefs.mode : 'auto';
    if (mode === 'off') return null;
    const skip = waveOutSkipReason(body);
    if (skip) { WAVE_OUT_STATE.skip = skip; return null; }
    const tools = Array.isArray(body.tools) ? body.tools : [];
    const useText = mode === 'text' || (mode === 'auto' && !tools.length);
    try {
        if (!useText) {
            const clientToolNames = collectToolNames(tools);
            body.tools = [...tools, buildToolDefinition(WAVE_OUT_TOOL)];
            body.tool_choice = 'auto';
            const control = buildControlPrompt(WAVE_OUT_TOOL);
            const last = body.messages[body.messages.length - 1];
            if (last && typeof last.content === 'string') last.content = last.content + '\n\n' + control;
            else body.messages.push({ role: 'user', content: control });
            WAVE_OUT_STATE.skip = '';
            return { mode: 'native', toolName: WAVE_OUT_TOOL, clientToolNames, streaming: body.stream === true, unescape: prefs.unescape === true };
        }
        const last = body.messages[body.messages.length - 1];
        if (last && typeof last.content === 'string') last.content = last.content + '\n\n' + waveOutTextInstruction();
        else body.messages.push({ role: 'user', content: waveOutTextInstruction() });
        WAVE_OUT_STATE.skip = '';
        return { mode: 'text', streaming: body.stream === true, toolName: WAVE_OUT_TOOL, clientToolNames: new Set(), unescape: prefs.unescape === true };
    } catch (error) {
        WAVE_OUT_STATE.error = describeError(error);
        throw error;
    }
}

/* ---------------- 回包还原 ---------------- */
async function waveOutRewrite(response, plan) {
    try {
        if (!response || !response.body) return response;
        if (!response.ok) { WAVE_OUT_STATE.error = 'HTTP ' + response.status + '：接口报错，本轮没有改写'; WAVE_OUT_STATE.skip = 'HTTP ' + response.status + '：接口报错，本轮没有改写'; return response; }
        plan = { ...plan, streaming: response.headers.get('content-type')?.includes('text/event-stream') === true };
        if (plan.mode === 'text') return await waveOutTextRewrite(response, plan);
        if (plan.streaming) {
            return rewriteEventStream(response, plan.toolName, plan.clientToolNames, stats => waveOutNote(stats, ''), plan.unescape);
        }
        const result = await rewriteJsonResponse(response, plan.toolName, plan.clientToolNames, plan.unescape);
        if (result && result.recovered) {
            waveOutNote({ emittedChars: result.recovered.chars, plainWon: result.recovered.plainWon }, '');
        }
        return (result && result.response) || response;
    } catch (error) {
        WAVE_OUT_STATE.error = describeError(error);
        throw error;
    }
}

function waveOutExtractText(text) {
    const source = String(text || '');
    const open = source.indexOf(WAVE_OUT_OPEN);
    const close = source.lastIndexOf(WAVE_OUT_CLOSE);
    let out = source;
    if (open >= 0 && close > open) out = source.slice(open + WAVE_OUT_OPEN.length, close);
    else if (open >= 0) out = source.slice(open + WAVE_OUT_OPEN.length);
    else if (close >= 0) out = source.slice(0, close);
    return out.replace(/^\s+/, '').replace(/\s+$/, '');
}

function waveOutCollectText(raw, streaming) {
    let text = '';
    function take(frame) {
        const message = frame.choices?.[0]?.delta ?? frame.choices?.[0]?.message;
        if (message?.tool_calls?.length) throw Error('文本通道收到未处理的工具调用');
        if (typeof message?.content === 'string') text += message.content;
    }
    if (streaming) {
        for (const line of raw.split('\n')) {
            if (!line.startsWith('data:')) continue;
            const data = line.slice(5).trim();
            if (data && data !== '[DONE]') take(JSON.parse(data));
        }
    } else {
        take(JSON.parse(raw));
    }
    return text;
}

function waveOutBuildResponse(container, streaming, text) {
    if (streaming) {
        const chunk = {
            candidates: [{ index: 0, content: { role: 'model', parts: [{ text }] } }],
            choices: [{ index: 0, delta: { content: text }, finish_reason: null }],
        };
        const end = {
            candidates: [{ index: 0, content: { role: 'model', parts: [{ text: '' }] }, finishReason: 'STOP' }],
            choices: [{ index: 0, delta: {}, finish_reason: 'stop' }],
        };
        const body = 'data: ' + JSON.stringify(chunk) + '\n\ndata: ' + JSON.stringify(end) + '\n\ndata: [DONE]\n\n';
        return new Response(body, { status: 200, headers: { 'content-type': 'text/event-stream' } });
    }
    const body = JSON.stringify({
        choices: [{ index: 0, message: { role: 'assistant', content: text }, finish_reason: 'stop' }],
        candidates: [{ index: 0, content: { role: 'model', parts: [{ text }] }, finishReason: 'STOP' }],
    });
    return new Response(body, { status: 200, headers: { 'content-type': 'application/json' } });
}

async function waveOutTextRewrite(response, plan) {
    const raw = await response.text();
    const text = waveOutDecodeText(waveOutExtractText(waveOutCollectText(raw, plan.streaming)), plan.unescape);
    waveOutNote({ emittedChars: text.length, textMode: true }, '');
    return waveOutBuildResponse(null, plan.streaming, text);
}

