    const skip = WAVE_OUT_STATE.skip ? '<p data-wave-out-note>上一轮没有接管：' + waveEscape(WAVE_OUT_STATE.skip) + '</p>' : '';
    const err = WAVE_OUT_STATE.error ? '<p data-wave-out-note>最近一次出错：' + waveEscape(WAVE_OUT_STATE.error) + '</p>' : '';
    const style = '<style>[data-wave-out]{margin-top:14px;padding:14px 16px;border:1px solid #b9e5ef;border-radius:16px;background:linear-gradient(180deg,#f6fdff,#fff);color:#153e52}[data-wave-out] h3{margin:0;font-size:15px;font-weight:750;letter-spacing:.02em}[data-wave-out-head]{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:8px}[data-wave-out-badge]{font:600 12px/1.5 system-ui,sans-serif;padding:3px 10px;border-radius:20px;background:#e7faff;color:#087caa;border:1px solid #b9e5ef;white-space:nowrap}[data-wave-out-detail]{margin:8px 0 0;font-size:13px;line-height:1.7}[data-wave-out-note]{margin:6px 0 0;font-size:12px;line-height:1.65;color:#8b4438}[data-wave-out-actions]{display:flex;flex-wrap:wrap;gap:8px;margin-top:10px}[data-wave-out-actions] button{font:600 13px/1.4 system-ui,sans-serif;padding:7px 14px;border-radius:999px;border:1px solid #087caa;background:#087caa;color:#fff;cursor:pointer}[data-wave-out-actions] button[data-active="false"]{background:#fff;color:#087caa}[data-wave-shield-actions] button[data-active="false"]{background:#fff;color:#087caa}[data-wave-shield-actions] button[data-active="true"]{background:#087caa;color:#fff}</style>';
    const head = '<div data-wave-out-head><h3>输出通道 · 防截断</h3><span data-wave-out-badge>' + badge + '</span></div>';
    const detail = '<p data-wave-out-detail>' + last + '</p><p data-wave-out-detail>' + waveEscape(WAVE_OUT_HINTS[mode] || '') + '</p>' + skip + err;
    const actions = '<div data-wave-out-actions><button type="button" data-wave-out-cycle="1" data-active="' + (mode !== 'off') + '">切换模式</button><button type="button" data-wave-out-unescape="1" aria-pressed="' + WAVE_OUT_STATE.unescape + '" data-active="' + WAVE_OUT_STATE.unescape + '">额外转义修复：' + (WAVE_OUT_STATE.unescape ? '开' : '关') + '</button></div>'
        + '<p data-wave-out-detail>仅在正文多出字面的 \\n、\\r 等符号时开启：再还原一层转义，会影响代码和路径中的同类写法。</p>';
    return style + '<section data-wave-out>' + head + detail + actions + '</section>';
}

  const COMMON_CONTENT_KEYS = [
    "content", "actual_content", "text", "output", 
    "response", "reply", "message", "result", "ans", "answer"
  ];
  const HIGH_SURROGATE_START = 55296; // 0xD800
  const HIGH_SURROGATE_END = 56319;   // 0xDBFF
  const LOW_SURROGATE_START = 56320;  // 0xDC00
  const LOW_SURROGATE_END = 57343;    // 0xDFFF
  const MAX_KEY_SCAN = 500;

  const SIMPLE_ESCAPES = {
    '"': '"', "\\": "\\", "/": "/", b: "\b", f: "\f", n: "\n", r: "\r", t: "\t"
  };

  class IncrementalContentDecoder {
    state = "init";
    keyScan = "";
    pendingEscape = "";
    pendingQuote = false;
    highSurrogate = 0;
    emittedAny = false;

    feed(fragment) {
      if (!fragment) return "";
      let out = "";
      let source = fragment;

      if (this.pendingQuote) {
        this.pendingQuote = false;
        const rest = source.replace(/^[\s]*/, "");
        if (rest.startsWith("}") || rest === "") {
          this.state = "completed";
          return "";
        }
        out += '"';
      }

      if (this.pendingEscape) {
        source = this.pendingEscape + source;
        this.pendingEscape = "";
      }

      let i = 0;
      while (i < source.length) {
        const char = source[i];
        switch (this.state) {
          case "init":
            if (char === "{" || char === '"') {
              this.state = "lookingForKey";
              if (char === '"') this.keyScan = '"';
            } else if (!/\s/.test(char)) {
              this.state = "rawText";
              out += char;
            }
            i += 1;
            break;

          case "lookingForKey":
            this.keyScan += char;
            i += 1;
            if (COMMON_CONTENT_KEYS.some((k) => this.keyScan.includes(`"${k}"`)) || /"[\w\-]+"\s*$/.test(this.keyScan)) {
              this.state = "lookingForColon";
              this.keyScan = "";
            } else if (this.keyScan.length > MAX_KEY_SCAN) {
              this.state = "rawText";
            }
            break;

          case "lookingForColon":
            if (char === ":") this.state = "lookingForQuote";
            else if (char === '"') this.state = "inString";
            i += 1;
            break;

          case "lookingForQuote":
            if (char === '"') this.state = "inString";
            else if (!/\s/.test(char)) {
              this.state = "rawText";
              out += char;
            }
            i += 1;
            break;

          case "inString": {
            const consumed = this.consumeStringChar(source, i);
            out += consumed.text;
            if (consumed.stop) i = source.length;
            else i += consumed.width;
            break;
          }

          case "rawText": {
            out += char;
            i += 1;
            break;
          }

          case "completed": {
            const rest = source.slice(i).trim();
            if (rest !== "" && rest !== "}" && rest !== "},") {
              this.state = "inString";
              break;
            }
            i = source.length;
            break;
          }

          case "error":
            this.state = "rawText";
            break;
        }
      }

      if (out) this.emittedAny = true;
      return out;
    }

    consumeStringChar(source, index) {
      const char = source[index];
      if (char === "\\") {
        const next = source[index + 1];
        if (next === undefined) {
          this.pendingEscape = "\\";
          return { text: "", width: 0, stop: true };
        }
        if (next === "u") {
          const hex = source.slice(index + 2, index + 6);
          if (hex.length < 4) {
            this.pendingEscape = source.slice(index);
            return { text: "", width: 0, stop: true };
          }
          const code = Number.parseInt(hex, 16);
          if (Number.isNaN(code)) return { text: `\\u${hex}`, width: 6, stop: false };
          if (code >= HIGH_SURROGATE_START && code <= HIGH_SURROGATE_END) {
            this.highSurrogate = code;
            return { text: "", width: 6, stop: false };
          }
          if (code >= LOW_SURROGATE_START && code <= LOW_SURROGATE_END && this.highSurrogate) {
            const combined = 65536 + ((this.highSurrogate - HIGH_SURROGATE_START) << 10) + (code - LOW_SURROGATE_START);
            this.highSurrogate = 0;
            return { text: String.fromCodePoint(combined), width: 6, stop: false };
          }
          return { text: String.fromCharCode(code), width: 6, stop: false };
        }

        const simple = SIMPLE_ESCAPES[next];
        if (simple !== undefined) return { text: simple, width: 2, stop: false };
        return { text: char + next, width: 2, stop: false };
      }

      if (char === '"') {
        const rest = source.slice(index + 1);
        if (rest === "") {
          this.pendingQuote = true;
          return { text: "", width: 0, stop: true };
        }
        if (rest.replace(/^[\s]*/, "").startsWith("}")) {
          this.state = "completed";
          return { text: "", width: 0, stop: true };
        }
        return { text: '"', width: 1, stop: false };
      }

      return { text: char, width: 1, stop: false };
    }

    finish() {
      let out = "";
      if (this.pendingQuote && !this.emittedAny) out += '"';
      this.pendingQuote = false;
      if (this.pendingEscape) {
        out += this.pendingEscape;
        this.pendingEscape = "";
      }
      if (out) this.emittedAny = true;
      return out;
    }
  }

  // ===================================================================================
  // 5. 万能参数提取与容错清洗 (readArgsContent)
  // ===================================================================================

  function extractContentFromObject(obj) {
    if (!obj || typeof obj !== "object") return undefined;
    for (const key of COMMON_CONTENT_KEYS) {
      if (typeof obj[key] === "string" && obj[key].length > 0) {
        return obj[key];
      }
    }
    let best = undefined;
    for (const [k, v] of Object.entries(obj)) {
      if (typeof v === "string" && v.length > 0) {
        if (!best || v.length > best.length) best = v;
      } else if (v && typeof v === "object") {
        const nested = extractContentFromObject(v);
        if (nested && (!best || nested.length > best.length)) best = nested;
      }
    }
    return best;
  }

  function readArgsContent(args) {
    if (typeof args === "object" && args !== null) {
      return extractContentFromObject(args);
    }
    if (typeof args === "string") {
      const trimmed = args.trim();
      if (!trimmed) return undefined;

      try {
        const parsed = JSON.parse(trimmed);
        if (typeof parsed === "string") return parsed;
        if (typeof parsed === "object" && parsed !== null) {
          const extracted = extractContentFromObject(parsed);
          if (typeof extracted === "string") return extracted;
        }
      } catch {}

      const cleaned = trimmed.replace(/^```(?:json)?\s*/i, "").replace(/\s*```$/, "").trim();
      if (cleaned !== trimmed) {
        try {
          const parsed = JSON.parse(cleaned);
          if (typeof parsed === "string") return parsed;
          if (typeof parsed === "object" && parsed !== null) {
            const extracted = extractContentFromObject(parsed);
            if (typeof extracted === "string") return extracted;
          }
        } catch {}
      }

      const decoder = new IncrementalContentDecoder();
      const salvaged = decoder.feed(cleaned) + decoder.finish();
      if (salvaged && salvaged.trim().length > 0) return salvaged;

      const match = cleaned.match(/"(?:content|actual_content|text|output|response|message)"\s*:\s*"((?:[^"\\]|\\.)*)/i);
      if (match && match[1]) {
        try {
          return JSON.parse(`"${match[1]}"`);
        } catch {
          return match[1].replace(/\\n/g, "\n").replace(/\\"/g, '"');
        }
      }

      if (!cleaned.startsWith("{") && !cleaned.startsWith("[")) {
        return cleaned;
      }
    }
    return undefined;
  }

  // ===================================================================================
  // 6. 工具名匹配与请求体构造 (Request Preparer)
  // ===================================================================================

  function bareToolName(candidate) {
    return candidate.slice(candidate.lastIndexOf(":") + 1);
  }

  function matchesToolName(candidate, toolName) {
    if (typeof candidate !== "string" || !candidate || !toolName) return false;
    if (candidate === toolName) return true;
    return bareToolName(candidate) === toolName;
  }

  const NO_CLIENT_TOOLS = new Set();
  function classifyToolName(candidate, toolName, clientToolNames = NO_CLIENT_TOOLS) {
    if (typeof candidate !== "string" || !candidate) return "client";
    return candidate === toolName ? "own" : "client";
  }

  function collectToolNames(tools) {
    const names = new Set();
    if (!Array.isArray(tools)) return names;
    for (const tool of tools) {
      const name = tool?.function?.name;
      if (typeof name === "string" && name) names.add(name);
    }
    return names;
  }

  function callerControlsTools(body) {
    const choice = body["tool_choice"];
    if (choice === "none") return "调用方明确禁用了工具调用 (tool_choice=none)";
    if (choice === "required") return "调用方强制了特定工具调用 (tool_choice=required)";
    if (choice && typeof choice === "object") return "调用方已固定特定工具";
    return undefined;
  }

  function buildToolDefinition(name = WAVE_OUT_TOOL) {
    return {
      type: "function",
      function: {
        name,
        description: TOOL_DESCRIPTION, // "图灵"
        parameters: {
          type: "object",
          properties: {
            content: {
              type: "string",
              description: "The complete final reply shown to the user."
            }
          },
          required: ["content"]
        }
      }
    };
  }

  function buildControlPrompt(toolName = WAVE_OUT_TOOL) {
    return `${TOOL_DESCRIPTION}\nCall the \`${toolName}\` function exactly once and put your complete final reply in its \`content\` argument. Do not write any of the final reply outside that call. Use any other available tools normally when they are needed.`;
  }

  function findAnchor(messages, anchors) {
    for (let index = 0; index < messages.length; index += 1) {
      const content = messages[index]?.content;
      if (typeof content === "string") {
        for (const anchor of anchors) {
          if (content.includes(anchor)) return index;
        }
      }
    }
    return -1;
  }

  function isReferenceCall(name, clientToolNames = NO_CLIENT_TOOLS) {
    return name === TOOL_NAME && clientToolNames.has(TOOL_NAME);
  }

  function readReferenceContent(args) {
    try { if (typeof args === "string") args = JSON.parse(args); } catch { return undefined; }
    if (!args || typeof args !== "object" || Array.isArray(args)) return undefined;
    for (const key of ["content", "actual_content", "text"]) {
      if (typeof args[key] === "string" && args[key].trim()) return args[key];
    }
    return undefined;
  }

  function hasReferenceCall(chunk, names) {
    const choices = Array.isArray(chunk.choices) ? chunk.choices : [];
    const candidates = Array.isArray(chunk.candidates) ? chunk.candidates : [];
    return choices.some(c => {
      const calls = c?.delta?.tool_calls ?? c?.message?.tool_calls;
      return Array.isArray(calls) && calls.some(call => isReferenceCall(call?.function?.name, names));
    }) || candidates.some(c => Array.isArray(c?.content?.parts)
      && c.content.parts.some(part => isReferenceCall(part?.functionCall?.name, names)));
  }

  // Hold only a mistaken reference call and subsequent chunks until its full arguments are known.
  // Empty, incomplete and unrelated calls are replayed without changing their protocol fields.
  function repairReferenceChunks(entries, toolName, names) {
    const groups = new Map(), activeGoogle = new Map(), owners = [], removed = new Set();
    let serial = 0;
    const add = (key, name, args, item, fn, parent, field, google) => {
      let group = groups.get(key);
      if (!group) { group = { name, raw: "", args: undefined, partial: {}, items: [], google }; groups.set(key, group); }
      if (name) group.name = name;
      if (typeof args === "string") group.raw += args;
      else if (args && typeof args === "object") {
        const previous = group.args || {};
        group.args = { ...previous, ...args };
        for (const key of ["content", "actual_content", "text"]) {
          const old = previous[key], next = args[key];
          if (typeof old === "string" && typeof next === "string") group.args[key] = next.startsWith(old) ? next : old.startsWith(next) ? old : old + next;
        }
      }
      for (const fragment of Array.isArray(fn.partialArgs) ? fn.partialArgs : []) {
        const match = /^\$\.(content|actual_content|text)$/.exec(fragment?.jsonPath || "");
        if (match && typeof fragment.stringValue === "string") group.partial[match[1]] = (group.partial[match[1]] || "") + fragment.stringValue;
      }
      group.items.push({ item, fn });
      owners.push({ parent, field });
      return group;
    };
    for (const { chunk } of entries) {
      for (const choice of Array.isArray(chunk.choices) ? chunk.choices : []) {
        const delta = choice?.delta || choice?.message;
        if (!Array.isArray(delta?.tool_calls)) continue;
        for (const call of delta.tool_calls) {
          if (!call?.function) continue;
          add(`o:${choice.index || 0}:${call.index || 0}`, call.function.name, call.function.arguments, call, call.function, delta, "tool_calls", false);
        }
      }
      for (const candidate of Array.isArray(chunk.candidates) ? chunk.candidates : []) {
        const content = candidate?.content;
        if (!Array.isArray(content?.parts)) continue;
        const index = candidate.index || 0;
        for (const part of content.parts) {
          const call = part?.functionCall;
          if (!call) continue;
          let active = activeGoogle.get(index);
          if (!active || (call.name && active.name !== call.name)) active = { key: `g:${index}:${serial++}`, name: call.name };
          add(active.key, call.name, call.args, part, call, content, "parts", true);
          if (call.willContinue === true) activeGoogle.set(index, active); else activeGoogle.delete(index);
        }
      }
    }
    for (const group of groups.values()) {
      if (!isReferenceCall(group.name, names)) continue;
      const text = readReferenceContent(group.args) ?? readReferenceContent(group.raw) ?? readReferenceContent(group.partial);
      if (text === undefined) continue;
      const first = group.items[0];
      first.fn.name = `${toolName}_reference_${serial++}`;
      if (group.google) {
        first.fn.args = { content: text };
        delete first.fn.partialArgs;
        delete first.fn.willContinue;
        const signature = group.items.find(entry => entry.item.thoughtSignature !== undefined)?.item.thoughtSignature;
        if (signature !== undefined) first.item.thoughtSignature = signature;
      } else first.fn.arguments = JSON.stringify({ content: text });
      for (const entry of group.items.slice(1)) removed.add(entry.item);
    }
    for (const { parent, field } of owners) parent[field] = parent[field].filter(item => !removed.has(item));
  }

  class SseContentRewriter {
    constructor(toolName, clientToolNames = new Set(), unescape = false) {
      this.unescape = unescape;
      this.toolName = toolName;
      this.clientToolNames = clientToolNames;
    }

    referenceBuffer = null;
    states = new Map();
    stats = {
      syntheticSeen: false,
      contentConflict: false,
      plainWon: false,
      sawDone: false,
      decodedChars: 0,
      emittedChars: 0,
      decodedChunks: 0
    };

    lastChunkMeta = {
      id: "chatcmpl-turing",
      model: "unknown",
      created: Math.floor(Date.now() / 1000)
    };

    state(index, dialect) {
      let existing = this.states.get(index);
      if (!existing) {
        existing = {
          dialect,
          plain: "",
          sent: "",
          channels: new Map(),
          slotNames: new Map(),
          activeGoogleChannel: undefined,
          clientSeen: false,
          sawSynthetic: false
        };
        this.states.set(index, existing);
      }
      existing.dialect = dialect;
      return existing;
    }

    transformPayload(payload) {
      const trimmed = payload.trim();
      if (trimmed === "[DONE]") {
        this.stats.sawDone = true;
        return undefined;
      }
      let chunk;
      try {
        const parsed = JSON.parse(trimmed);
        if (!parsed || typeof parsed !== "object") return payload;
        chunk = parsed;
      } catch {
        return payload;
      }

      if (this.referenceBuffer || hasReferenceCall(chunk, this.clientToolNames)) {
        (this.referenceBuffer ??= []).push({ chunk, payload });
        return undefined;
      }
      return this.rewriteChunk(chunk, payload);
    }

    rewriteChunk(chunk, payload) {
      if (typeof chunk["id"] === "string") this.lastChunkMeta.id = chunk["id"];
      if (typeof chunk["model"] === "string") this.lastChunkMeta.model = chunk["model"];
      if (typeof chunk["created"] === "number") this.lastChunkMeta.created = chunk["created"];

      const choices = chunk["choices"];
      if (Array.isArray(choices)) return this.rewriteChoices(chunk, choices, payload);

      const candidates = chunk["candidates"];
      if (Array.isArray(candidates)) return this.rewriteCandidates(chunk, candidates, payload);

      return payload;
    }

    rewriteChoices(chunk, choices, payload) {
      let touched = false;
      let anythingToSend = false;

      for (const rawChoice of choices) {
        if (!rawChoice || typeof rawChoice !== "object") continue;
        const choice = rawChoice;
        const index = typeof choice["index"] === "number" ? choice["index"] : 0;
        const state = this.state(index, "openai");
        const field = choice["delta"] === undefined || choice["delta"] === null ? (choice["message"] && typeof choice["message"] === "object" ? "message" : "delta") : "delta";
        const delta = choice[field] ?? {};
        const originalContent = typeof delta["content"] === "string" ? delta["content"] : "";
        let streamedText = "";

        const toolCalls = delta["tool_calls"];
        if (Array.isArray(toolCalls)) {
          const { handled, decoded, remaining } = this.consumeToolCalls(state, toolCalls);
          streamedText += decoded;
          if (handled) touched = true;
          if (remaining.length > 0) {
            state.clientSeen = true;
            delta["tool_calls"] = remaining;
            anythingToSend = true;
          } else if (toolCalls.length > 0 && handled) {
            delete delta["tool_calls"];
            touched = true;
          }
        }

        if (originalContent) {
          if (state.sawSynthetic) {
            touched = true;
            delete delta["content"];
            state.plain += originalContent;
          } else {
            anythingToSend = true;
          }
        }

        if (streamedText) {
          delta["content"] = streamedText;
          anythingToSend = true;
        }

        const finish = choice["finish_reason"];
        if (finish !== null && finish !== undefined) {
          touched = true;
          anythingToSend = true;
          const tail = this.finalizeChoice(state);
          if (tail) {
            delta["content"] = (delta["content"] ?? "") + tail;
          }
          if (state.sawSynthetic && !state.clientSeen && finish === "tool_calls") {
            choice["finish_reason"] = "stop";
          }
          if (delta["content"] === undefined) {
            delta["content"] = "";
          }
        }

        if (Object.keys(delta).length > 0) anythingToSend = true;
        choice[field] = delta;
      }

      if (!touched) return payload;
      if (!anythingToSend) return undefined;
      return JSON.stringify(chunk);
    }

    /** 改写 Google Gemini 格式，并同时注入 OpenAI choices 字段 */
    rewriteCandidates(chunk, candidates, payload) {
      let touched = false;
      let anythingToSend = false;

      for (const rawCandidate of candidates) {
        if (!rawCandidate || typeof rawCandidate !== "object") continue;
        const candidate = rawCandidate;
        const index = typeof candidate["index"] === "number" ? candidate["index"] : 0;
        const state = this.state(index, "google");
        const rawContent = candidate["content"];
        const content = rawContent && typeof rawContent === "object" ? rawContent : {};
        const parts = content["parts"];
        let streamedText = "";
        const kept = [];
        let savedThoughtSig = undefined;

        if (Array.isArray(parts)) {
          for (const rawPart of parts) {
            if (!rawPart || typeof rawPart !== "object") {
              kept.push(rawPart);
              continue;
            }
            const part = rawPart;
            if (part["thoughtSignature"] && !savedThoughtSig) {
              savedThoughtSig = part["thoughtSignature"];
            }
            const call = part["functionCall"];
            if (call && typeof call === "object") {
              const consumed = this.consumeGoogleCall(state, call);
              if (!consumed.handled) {
                state.clientSeen = true;
                kept.push(rawPart);
                continue;
              }
              streamedText += consumed.decoded;
              touched = true;
              continue;
            }
            if (part["thought"] === true) {
              kept.push(rawPart);
              continue;
            }
            if (typeof part["text"] === "string" && part["text"]) {
              if (state.sawSynthetic) {
                touched = true;
                state.plain += part["text"];
                continue;
              } else {
                kept.push(rawPart);
                anythingToSend = true;
                continue;
              }
            }
            kept.push(rawPart);
          }
        }

        let emitted = streamedText;
        const finish = candidate["finishReason"];
        if (finish !== null && finish !== undefined) {
          touched = true;
          anythingToSend = true;
          emitted += this.finalizeChoice(state);
        }

        if (!touched) continue;

        // 规范化 finishReason：当拦截到防截断工具调用时，强制改为 stop，杜绝前端当作工具调用丢弃
        let normalizedFinish = finish ? String(finish).toLowerCase() : null;
        if (state.sawSynthetic && !state.clientSeen && (normalizedFinish === "tool_calls" || normalizedFinish === "stop" || finish !== undefined)) {
          normalizedFinish = "stop";
        }

        // 1. 改写原生 Gemini parts
        const nextParts = [];
        if (emitted) {
          const textPart = { text: emitted };
          if (savedThoughtSig) textPart["thoughtSignature"] = savedThoughtSig;
          nextParts.push(textPart);
        }
        nextParts.push(...kept);

        if (nextParts.length > 0 || Array.isArray(parts)) {
          content["parts"] = nextParts;
          if (typeof content["role"] !== "string") content["role"] = "model";
          candidate["content"] = content;
        }

        // 2. 核心双向兼容：同时为 chunk 注入标准 OpenAI choices 格式！
        // 彻底解决酒馆 chat-completions 端点读不到 choices 导致气泡空回的问题！
        if (emitted || normalizedFinish) {
          if (normalizedFinish) candidate["finishReason"] = normalizedFinish.toUpperCase();
          chunk["choices"] = [
            {
              index,
              delta: { content: emitted || "" },
              finish_reason: normalizedFinish
            }
          ];
          anythingToSend = true;
        }

        if (nextParts.length > 0) anythingToSend = true;
      }

      if (!touched) return payload;
      if (!anythingToSend) return undefined;
      return JSON.stringify(chunk);
    }

    consumeGoogleCall(state, call) {
      const name = call["name"];
      let channelName;
      if (typeof name === "string" && name) {
        if (classifyToolName(name, this.toolName, this.clientToolNames) === "client") {
          state.activeGoogleChannel = undefined;
          return { handled: false, decoded: "" };
        }
        channelName = bareToolName(name);
        state.activeGoogleChannel = channelName;
      } else {
        channelName = state.activeGoogleChannel;
      }

      if (channelName === undefined) {
        return { handled: false, decoded: "" };
      }

      this.markSynthetic(state);
      const channel = this.channel(state, channelName);
      let text = "";

      const partialArgs = call["partialArgs"];
      if (Array.isArray(partialArgs)) text += readPartialArgs(partialArgs);
      if (call["args"] !== undefined) text += decodeGoogleArgs(channel, call["args"]);

      if (call["willContinue"] !== true) state.activeGoogleChannel = undefined;

      AntiTruncationDebugger.recordToolCall(call, "sse-gemini-call", text);
      return { handled: true, decoded: this.absorb(state, channel, text) };
    }

    markSynthetic(state) {
      if (state.sawSynthetic) return;
      state.sawSynthetic = true;
      this.stats.syntheticSeen = true;
    }

    channel(state, name) {
      let channel = state.channels.get(name);
      if (!channel) {
        channel = { decoder: new IncrementalContentDecoder(), text: "" };
        state.channels.set(name, channel);
      }
      return channel;
    }

    absorb(state, channel, text) {
      if (!text) return "";
      channel.text += text;
      this.stats.decodedChunks += 1;

      // 同步实时吐到悬浮监视器中！
      FloatingMonitor.append(text);

      if (this.unescape || state.plain !== "" || state.channels.size > 1) return "";
      state.sent += text;
      this.stats.decodedChars += text.length;
      this.stats.emittedChars += text.length;
      return text;
    }

    consumeToolCalls(state, toolCalls) {
      let handled = false;
      let decoded = "";
      const remaining = [];

      for (const rawCall of toolCalls) {
        if (!rawCall || typeof rawCall !== "object") {
          remaining.push(rawCall);
          continue;
        }
        const call = rawCall;
        const callIndex = typeof call["index"] === "number" ? call["index"] : 0;
        const fn = call["function"] ?? {};
        const name = typeof fn["name"] === "string" ? fn["name"] : "";

        let channelName = state.slotNames.get(callIndex);
        if (name) {
          const origin = classifyToolName(name, this.toolName, this.clientToolNames);
          if (origin === "client") {
            channelName = undefined;
            state.slotNames.delete(callIndex);
          } else {
            channelName = bareToolName(name);
            state.slotNames.set(callIndex, channelName);
          }
        }

        if (channelName === undefined) {
          remaining.push(rawCall);
          continue;
        }

        handled = true;
        this.markSynthetic(state);
        const channel = this.channel(state, channelName);
        const args = fn["arguments"];
        if (args !== undefined && args !== null) {
          const rawArgStr = typeof args === "string" ? args : JSON.stringify(args);
          const chunkDecoded = channel.decoder.feed(rawArgStr);
          decoded += this.absorb(state, channel, chunkDecoded);
          AntiTruncationDebugger.recordToolCall(rawCall, "sse-tool_calls", chunkDecoded);
        }
      }

      return { handled, decoded, remaining };
    }

    finalizeChoice(state) {
      let best = "";
      let bestIsPlain = false;
      let contenders = 0;

      for (const channel of state.channels.values()) {
        channel.text += channel.decoder.finish();
        if (channel.text) contenders += 1;
        if (channel.text.length > best.length) {
          best = channel.text;
          bestIsPlain = false;
        }
        channel.text = "";
      }

      if (state.plain) {
        contenders += 1;
        if (state.plain.length > best.length) {
          best = state.plain;
          bestIsPlain = true;
        }
      }
      state.plain = "";

      if (contenders > 1) {
        this.stats.contentConflict = true;
        if (bestIsPlain) this.stats.plainWon = true;
      }

      if (!bestIsPlain) best = waveOutDecodeText(best, this.unescape);
      const tail = best.startsWith(state.sent) ? best.slice(state.sent.length) : best;
      state.sent += tail;
      this.stats.emittedChars += tail.length;
      if (!bestIsPlain) this.stats.decodedChars += tail.length;

      if (tail) FloatingMonitor.append(tail);
      return tail;
    }

    finalizePending() {
      const payloads = [];
      if (this.referenceBuffer) {
        const entries = this.referenceBuffer;
        this.referenceBuffer = null;
        repairReferenceChunks(entries, this.toolName, this.clientToolNames);
        for (const { chunk } of entries) {
          const rewritten = this.rewriteChunk(chunk, JSON.stringify(chunk));
          if (rewritten !== undefined) payloads.push(rewritten);
        }
      }

      const { id, model, created } = this.lastChunkMeta;
      for (const [index, state] of this.states) {
        const pending = this.finalizeChoice(state);
        if (!pending) continue;

        // 双向输出保护
        payloads.push(
          JSON.stringify({
            id,
            object: "chat.completion.chunk",
            created,
            model,
            choices: [{ index, delta: { content: pending }, finish_reason: null }],
            candidates: [{ index, content: { role: "model", parts: [{ text: pending }] } }]
          })
        );
      }
      return payloads;
    }
  }

  function readPartialArgs(partialArgs) {
    let text = "";
    for (const rawFragment of partialArgs) {
      if (!rawFragment || typeof rawFragment !== "object") continue;
      const fragment = rawFragment;
      const path = typeof fragment["jsonPath"] === "string" ? fragment["jsonPath"].trim() : "";
      if (path === "$.content" || path.includes("content") || path.includes("actual_content")) {
        const value = fragment["stringValue"];
        if (typeof value === "string") text += value;
      }
    }
    return text;
  }

  function decodeGoogleArgs(channel, args) {
    if (typeof args === "string") return args ? channel.decoder.feed(args) : "";
    if (args && typeof args === "object") {
      const content = extractContentFromObject(args);
      if (typeof content !== "string" || !content) return "";
      if (!channel.text) return content;
      if (content.startsWith(channel.text)) return content.slice(channel.text.length);
      if (channel.text.startsWith(content)) return "";
      return content;
    }
    return "";
  }

  // ===================================================================================
  // 8. 响应重写与双向注入 (Stream & JSON Rewriter)
  // ===================================================================================

  function findSseBoundary(buf) {
    const match = /\r\n\r\n|\n\n|\r\r/.exec(buf);
    if (!match) return null;
    return {
      index: match.index,
      length: match[0].length
    };
  }

  function rewriteEventStream(response, toolName, clientToolNames, onComplete, unescape = false) {
    const rewriter = new SseContentRewriter(toolName, clientToolNames, unescape);
    const decoder = new TextDecoder();
    const encoder = new TextEncoder();
    let buffer = "";
    let doneEmitted = false;

    // 向下游发送结束信号与 [DONE]
    function emitDone(controller) {
      if (doneEmitted) return;
      doneEmitted = true;

      // 1. 刷出任何 pending 的未发分块
      for (const payload of rewriter.finalizePending()) {
        controller.enqueue(encoder.encode(`data: ${payload}\n\n`));
      }

      // 2. 注入标准 [DONE] 标记，酒馆前端收到后立即结束流式循环并定稿气泡！
      controller.enqueue(encoder.encode("data: [DONE]\n\n"));
      rewriter.stats.sawDone = true;

      // 3. 立即更新监视器状态与统计
      FloatingMonitor.finishSession();
      AntiTruncationDebugger.recordStats(rewriter.stats);
      Logger.info(`流式传输防截断正文已就绪并通知前端定稿 [累计 ${rewriter.stats.emittedChars} 字]`);
      onComplete?.(rewriter.stats);
    }

    const transformStream = new TransformStream({
      transform(chunk, controller) {
        // 若已向下游发送了 [DONE]，上游后续的冗余空分块（如后端的心跳或空候选体）直接静默忽略
        if (doneEmitted) return;

        buffer += decoder.decode(chunk, { stream: true });
        let boundary = findSseBoundary(buffer);

        while (boundary !== null) {
          const rawEvent = buffer.slice(0, boundary.index);
          buffer = buffer.slice(boundary.index + boundary.length);

          if (rawEvent.trim()) {
            AntiTruncationDebugger.recordChunk(rawEvent);
            const rewritten = rewriteEvent(rewriter, rawEvent);
            if (rewritten !== undefined) {
              controller.enqueue(encoder.encode(rewritten + "\n\n"));
            }
            if (rewriter.stats.sawDone) {
              emitDone(controller);
              controller.terminate();
              return;
            }

          }
          boundary = findSseBoundary(buffer);
        }
      },
      flush(controller) {
        if (buffer.trim() && !doneEmitted) {
          const rest = buffer.trim();
          AntiTruncationDebugger.recordChunk(rest);
          const rewritten = rewriteEvent(rewriter, rest);
          if (rewritten !== undefined) {
            controller.enqueue(encoder.encode(rewritten + "\n\n"));
          }
        }
        emitDone(controller);
      }
    });

    const transformedBody = response.body.pipeThrough(transformStream);

    return new Response(transformedBody, {
      status: response.status,
      statusText: response.statusText,
      headers: response.headers
    });
  }

  function rewriteEvent(rewriter, rawEvent) {
    const lines = rawEvent.split(/\r?\n/);
    const out = [];
    let sawData = false;
    let emittedData = false;

    for (const line of lines) {
      if (!line.startsWith("data:")) {
        out.push(line);
        continue;
      }
      sawData = true;
      const payload = line.slice("data:".length).replace(/^ /, "");
      const rewritten = rewriter.transformPayload(payload);
      if (rewritten !== undefined) {
        out.push(`data: ${rewritten}`);
        emittedData = true;
      }
    }

    if (sawData && !emittedData) return undefined;
    return out.join("\n");
  }

  async function rewriteJsonResponse(response, toolName, clientToolNames, unescape = false) {
    let parsed;
    try {
      parsed = await response.clone().json();
    } catch (error) {
      Logger.warn(`响应非合法 JSON: ${describeError(error)}`);
      return { response, recovered: undefined };
    }

    let recovered;
    try {
      const choices = parsed["choices"];
      if (Array.isArray(choices)) {
        recovered = unwrapOpenAiChoices(choices, toolName, clientToolNames, unescape);
      }
      const google = unwrapGoogleContent(parsed, toolName, clientToolNames, unescape);
      if (google !== undefined) recovered = mergeRecovery(recovered, google);

      // 非流式双向补全
      if (recovered && recovered.text) {
        FloatingMonitor.set(recovered.text);
        FloatingMonitor.finishSession();
        if (!parsed["choices"] || !Array.isArray(parsed["choices"])) {
          parsed["choices"] = [{ message: { role: "assistant", content: recovered.text }, finish_reason: "stop" }];
        }
      }
    } catch (error) {
      Logger.warn(`解析 JSON 回复失败: ${describeError(error)}`);
      return { response, recovered: undefined };
    }

    if (recovered === undefined) return { response, recovered };

    return {
      response: new Response(JSON.stringify(parsed), {
        status: response.status,
        statusText: response.statusText,
        headers: response.headers
      }),
      recovered
    };
  }

  function mergeRecovery(a, b) {
    if (!a) return b;
    return {
      text: a.text.length >= b.text.length ? a.text : b.text,
      chars: a.chars + b.chars,
      conflict: a.conflict || b.conflict,
      plainWon: a.plainWon || b.plainWon
    };
  }

  function longest(plain, carried) {
    let text = plain;
    let plainWon = true;
    for (const candidate of carried) {
      if (candidate.length >= text.length) {
        text = candidate;
        plainWon = false;
      }
    }
    const contenders = (plain ? 1 : 0) + carried.filter((entry) => entry !== "").length;
    return {
      text,
      chars: text.length,
      conflict: contenders > 1,
      plainWon: plainWon && contenders > 1
    };
  }

  function unwrapOpenAiChoices(choices, toolName, clientToolNames, unescape = false) {
    let recovered;
    for (const rawChoice of choices) {
      const choice = rawChoice;
      const message = choice["message"];
      if (!message) continue;
      const calls = message["tool_calls"];
      if (!Array.isArray(calls)) continue;
      const kept = [];
      const carried = [];

      for (const rawCall of calls) {
        const fn = rawCall?.function;
        const fnName = fn?.name ?? rawCall?.name ?? "";
        const reference = isReferenceCall(fnName, clientToolNames) ? readReferenceContent(fn?.arguments) : undefined;
        if (fn && (reference !== undefined || classifyToolName(fnName, toolName, clientToolNames) !== "client")) {
          const value = reference ?? readArgsContent(fn["arguments"]);
          AntiTruncationDebugger.recordToolCall(rawCall, "json-openAi", value);
          if (typeof value === "string") {
            carried.push(waveOutDecodeText(value, unescape));
            continue;
          }
        }
        kept.push(rawCall);
      }

      if (carried.length === 0) continue;

      const plain = typeof message["content"] === "string" ? message["content"] : "";
      const best = longest(plain, carried);
      message["content"] = best.text;
      recovered = mergeRecovery(recovered, best);

      if (kept.length > 0) {
        message["tool_calls"] = kept;
      } else {
        delete message["tool_calls"];
        if (choice["finish_reason"] === "tool_calls") choice["finish_reason"] = "stop";
      }
    }
    return recovered;
  }

  function unwrapGoogleContent(parsed, toolName, clientToolNames, unescape = false) {
    const rawContent = parsed["responseContent"] ?? (parsed["candidates"] ? parsed["candidates"][0]?.content : undefined);
    if (!rawContent || typeof rawContent !== "object") return undefined;
    const content = rawContent;
    const parts = content["parts"];
    if (!Array.isArray(parts)) return undefined;

    const kept = [];
    const carried = [];
    let plain = "";
    let signature;

    for (const rawPart of parts) {
      const part = rawPart;
      const call = part?.["functionCall"];
      const reference = isReferenceCall(call?.name, clientToolNames) ? readReferenceContent(call?.args) : undefined;
      if (call && (reference !== undefined || classifyToolName(call["name"], toolName, clientToolNames) !== "client")) {
        const value = reference ?? readArgsContent(call["args"]);
        AntiTruncationDebugger.recordToolCall(call, "json-google", value);
        if (typeof value === "string") {
          carried.push(waveOutDecodeText(value, unescape));
          if (part?.["thoughtSignature"] !== undefined) signature = part["thoughtSignature"];
          continue;
        }
      }
      if (part && part["thought"] !== true && typeof part["text"] === "string" && part["text"]) {
        plain += part["text"];
        if (signature === undefined && part["thoughtSignature"] !== undefined) {
          signature = part["thoughtSignature"];
        }
        continue;
      }
      kept.push(rawPart);
    }

    if (carried.length === 0) return undefined;

    const choices = parsed["choices"];
    const message = Array.isArray(choices) ? choices[0]?.message : undefined;
    const wrapped = typeof message?.["content"] === "string" ? message["content"] : "";
    const best = longest(plain.length >= wrapped.length ? plain : wrapped, carried);

    const textPart = { text: best.text };
    if (signature !== undefined) textPart["thoughtSignature"] = signature;
    content["parts"] = [textPart, ...kept];
    if (message) message["content"] = best.text;

    return best;
  }

  // ===================================================================================
  // 9. 全局 Fetch 拦截器 (AntiTruncationInterceptor)
  // ===================================================================================

  const FETCH_MARKER = "__TuringAntiTruncationFetch__";



